(6235569, 921168, 117534, '<td valign="top">This is very nice, I really like the lighting and the face I can see some ?tail lights? in the background. Really give the feel of a NIGHT photo instead of just a studio shot, I bet you''ve gotten some comments on the light being harsh, but In my opinion that only adds to the very real feel of this.  I say 8</td>', 'This is very nice, I really like the lighting and the face I can see some ?tail lights? in the background. Really give the feel of a NIGHT photo instead of just a studio shot, I bet you''ve gotten some comments on the light being harsh, but In my opinion that only adds to the very real feel of this.  I say 8', '2010-11-27 23:47:19.000000', NULL, 1),
(6235581, 921481, 117534, '<td valign="top">beautiful lighting, love the shallow dof and the golden background and that your model''s face color and features are very focused and color perfect</td>', 'beautiful lighting, love the shallow dof and the golden background and that your model''s face color and features are very focused and color perfect', '2010-11-27 23:51:50.000000', NULL, 1),
(6235589, 921669, 117534, '<td valign="top">I am chokeing I''m laughing so hard!! 10 for makeing my night!! Ah guess I should''ve mentioned I really liked your lighting and processing.. very good photo, Still makes me laugh but it''s a good photo too!</td>', 'I am chokeing I''m laughing so hard!! 10 for makeing my night!! Ah guess I should''ve mentioned I really liked your lighting and processing.. very good photo, Still makes me laugh but it''s a good photo too!', '2010-11-27 23:55:54.000000', NULL, 1),
(6235797, 921559, 74041, '<td valign="top">Its remids me of mona lisa :) good shades.</td>', 'Its remids me of mona lisa :) good shades.', '2010-11-28 07:13:12.000000', NULL, 1),
(6235847, 921648, 11769, '<td valign="top">Moody, obscure. Like it.</td>', 'Moody, obscure. Like it.', '2010-11-28 10:05:43.000000', NULL, 1),
(6235910, 921267, 114225, '<td valign="top">Fun photo. I like how the perspective makes the slide look enormous at the bottom.</td>', 'Fun photo. I like how the perspective makes the slide look enormous at the bottom.', '2010-11-28 10:47:57.000000', NULL, 1),
(6235912, 921653, 114225, '<td valign="top">This photo is making me dizzy! The buildings and person feel upright, while the rest of the people and the sidewalk are tilted. My mind hurts!</td>', 'This photo is making me dizzy! The buildings and person feel upright, while the rest of the people and the sidewalk are tilted. My mind hurts!', '2010-11-28 10:49:22.000000', NULL, 1),
(6235913, 921559, 114225, '<td valign="top">Pretty subject and nice photo. The overly soft skin isn''t appealing to me.</td>', 'Pretty subject and nice photo. The overly soft skin isn''t appealing to me.', '2010-11-28 10:49:55.000000', NULL, 1),
(6235914, 921650, 114225, '<td valign="top">Haha, nice job with making me laugh! the excitement in her face is wonderful...</td>', 'Haha, nice job with making me laugh! the excitement in her face is wonderful...', '2010-11-28 10:50:42.000000', NULL, 1),
(6235915, 921593, 114225, '<td valign="top">Very well done! Seemingly an instant classic.</td>', 'Very well done! Seemingly an instant classic.', '2010-11-28 10:51:09.000000', NULL, 1),
(6235916, 920882, 114225, '<td valign="top">Great use of a top hat. you just don''t see those much these days :)</td>', 'Great use of a top hat. you just don''t see those much these days :)', '2010-11-28 10:51:34.000000', NULL, 1),
(6235919, 921028, 114225, '<td valign="top">Cute photo. The straight on catchlights in the eyes are a bit distracting. Maybe use of some diffusion of reflection of the flash could help out.</td>', 'Cute photo. The straight on catchlights in the eyes are a bit distracting. Maybe use of some diffusion of reflection of the flash could help out.', '2010-11-28 10:54:38.000000', NULL, 1),
(6236039, 921391, 96751, '<td valign="top">Bizarre and intriguing.  Rather haunting too.</td>', 'Bizarre and intriguing.  Rather haunting too.', '2010-11-28 12:22:08.000000', NULL, 1),
(6236040, 921651, 96751, '<td valign="top">I like the premise, and wonderful capture of our recent full moon, but the subject looks rather disengaged from it all, and separate (and oblivious) to the majesty behind him), which only disengages me from the image.</td>', 'I like the premise, and wonderful capture of our recent full moon, but the subject looks rather disengaged from it all, and separate (and oblivious) to the majesty behind him), which only disengages me from the image.', '2010-11-28 12:23:38.000000', NULL, 1),
(6236041, 921037, 96751, '<td valign="top">"What a feeling...!!"  sorry.  Flashdance flashback.  Excellent use of negative space.</td>', '"What a feeling...!!"  sorry.  Flashdance flashback.  Excellent use of negative space.', '2010-11-28 12:24:13.000000', NULL, 1),
(6236042, 921481, 96751, '<td valign="top">Nighttime bokeh!  Fabulous.</td>', 'Nighttime bokeh!  Fabulous.', '2010-11-28 12:24:33.000000', NULL, 1),
(6236050, 921451, 96751, '<td valign="top">Very nicely done.  The lighting really even, the reflection is so clear.  The only thing I might have changed is a slightly tighter crop off the top to match the reflection.</td>', 'Very nicely done.  The lighting really even, the reflection is so clear.  The only thing I might have changed is a slightly tighter crop off the top to match the reflection.', '2010-11-28 12:28:10.000000', NULL, 1),
(6236052, 921653, 96751, '<td valign="top">Fabulous.  You really captured her spark.</td>', 'Fabulous.  You really captured her spark.', '2010-11-28 12:28:43.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6236054, 921336, 96751, '<td valign="top">Lovely, but the topazed hair looks too weird.</td>', 'Lovely, but the topazed hair looks too weird.', '2010-11-28 12:29:03.000000', NULL, 1),
(6236056, 921440, 96751, '<td valign="top">I like it!!  Maybe if it were just a tad less orange I''d like it even more, but I love the quirkiness, the pov, the attitude :-)</td>', 'I like it!!  Maybe if it were just a tad less orange I''d like it even more, but I love the quirkiness, the pov, the attitude :-)', '2010-11-28 12:30:14.000000', NULL, 1),
(6236061, 920892, 96751, '<td valign="top">It took a moment...  LOL!  I thought it was a door stop!  Clever title, and I love all the lines in the image.  Something for everyone: tilted, diagonal, circular, square, triangular.  Eye candy for the demented :-)</td>', 'It took a moment...  LOL!  I thought it was a door stop!  Clever title, and I love all the lines in the image.  Something for everyone: tilted, diagonal, circular, square, triangular.  Eye candy for the demented :-)', '2010-11-28 12:31:44.000000', NULL, 1),
(6236067, 921559, 96751, '<td valign="top">Although this is a lovely portrait, nothing about it says "night" to me.  This could just as easily have been taken in a studio.</td>', 'Although this is a lovely portrait, nothing about it says "night" to me.  This could just as easily have been taken in a studio.', '2010-11-28 12:32:50.000000', NULL, 1),
(6236069, 921073, 96751, '<td valign="top">Weird, this is very similar to the image just before, to which I also wrote: although this is a lovely portrait, nothing about it says "night" to me.  This could just as easily have been taken in a studio.<br/> <br/>I do like the unusual pov - it adds a lot of dimension.</td>', 'Weird, this is very similar to the image just before, to which I also wrote: although this is a lovely portrait, nothing about it says "night" to me.  This could just as easily have been taken in a studio. I do like the unusual pov - it adds a lot of dimension.', '2010-11-28 12:33:43.000000', NULL, 1),
(6236072, 920965, 96751, '<td valign="top">A really terrific capture, but the harsh shadows make me think this is daytime.</td>', 'A really terrific capture, but the harsh shadows make me think this is daytime.', '2010-11-28 12:34:30.000000', NULL, 1),
(6236076, 921517, 96751, '<td valign="top">OMG!  Too funny.  And wonderful.  Is this REALLY a nighttime shot?  Great detail and humor and story.</td>', 'OMG!  Too funny.  And wonderful.  Is this REALLY a nighttime shot?  Great detail and humor and story.', '2010-11-28 12:35:56.000000', NULL, 1),
(6236079, 921596, 96751, '<td valign="top">Magical.  Love the two "witnesses" on the rocks.  I love how the lovers seem to be emerging from the darkness and heading towards the glowing sand.</td>', 'Magical.  Love the two "witnesses" on the rocks.  I love how the lovers seem to be emerging from the darkness and heading towards the glowing sand.', '2010-11-28 12:36:49.000000', NULL, 1),
(6236082, 921133, 96751, '<td valign="top">Wicked good.  The light in the distance really creates exceptional depth and story.</td>', 'Wicked good.  The light in the distance really creates exceptional depth and story.', '2010-11-28 12:37:22.000000', NULL, 1),
(6236086, 921267, 96751, '<td valign="top">Sweet.  The obvious use of flash really adds a whimsical element to this image.</td>', 'Sweet.  The obvious use of flash really adds a whimsical element to this image.', '2010-11-28 12:37:53.000000', NULL, 1),
(6236089, 921490, 96751, '<td valign="top">I LOVE this!!!  The motion blur, the streaks of snow, the lighting, and the hint of trees, just terrific.  Was a street light the light source?</td>', 'I LOVE this!!!  The motion blur, the streaks of snow, the lighting, and the hint of trees, just terrific.  Was a street light the light source?', '2010-11-28 12:39:05.000000', NULL, 1),
(6236091, 921593, 96751, '<td valign="top">Inspired.  Great use of time lapse.  And incredibly crisp detail.</td>', 'Inspired.  Great use of time lapse.  And incredibly crisp detail.', '2010-11-28 12:40:12.000000', NULL, 1),
(6236093, 921483, 118154, '<td valign="top">Good night image.</td>', 'Good night image.', '2010-11-28 12:40:47.000000', NULL, 1),
