(6236096, 921391, 118154, '<td valign="top">OK, different idea.</td>', 'OK, different idea.', '2010-11-28 12:42:13.000000', NULL, 1),
(6236097, 921596, 118154, '<td valign="top">Don,t really class this as a portrait although I like it.</td>', 'Don,t really class this as a portrait although I like it.', '2010-11-28 12:42:16.000000', NULL, 1),
(6236098, 921656, 118154, '<td valign="top">Background is better than the portrait for me.</td>', 'Background is better than the portrait for me.', '2010-11-28 12:42:55.000000', NULL, 1),
(6236100, 921573, 96751, '<td valign="top">I like this a lot!  A study in contrasts, a social commentary, a killer street scene.  The only nit is I would have cropped off the bottom up to the vertical door frame at the center of the doors.</td>', 'I like this a lot!  A study in contrasts, a social commentary, a killer street scene.  The only nit is I would have cropped off the bottom up to the vertical door frame at the center of the doors.', '2010-11-28 12:43:11.000000', NULL, 1),
(6236102, 921365, 118154, '<td valign="top">Has a certain draw to it .</td>', 'Has a certain draw to it .', '2010-11-28 12:43:48.000000', NULL, 1),
(6236103, 921393, 96751, '<td valign="top">Moody, contemplative, sad.  Great combination of details and blur.  I especially love those two tiny glints off her earring.</td>', 'Moody, contemplative, sad.  Great combination of details and blur.  I especially love those two tiny glints off her earring.', '2010-11-28 12:44:07.000000', NULL, 1),
(6236106, 921483, 96751, '<td valign="top">There is promise in this image, but I feel it needs a tighter crop.  Also a higher, rather than lower, pov might have underscored her helplessness.</td>', 'There is promise in this image, but I feel it needs a tighter crop.  Also a higher, rather than lower, pov might have underscored her helplessness.', '2010-11-28 12:45:02.000000', NULL, 1),
(6236107, 921365, 96751, '<td valign="top">This feels very journalistic, and historic.  As though a candid moment from a Cold War state level discussion between opponents.  Marvelous.  So much captured.</td>', 'This feels very journalistic, and historic.  As though a candid moment from a Cold War state level discussion between opponents.  Marvelous.  So much captured.', '2010-11-28 12:46:43.000000', NULL, 1),
(6236108, 921669, 96751, '<td valign="top">Oh my, the incongruity is delightful.  But the look on her face reminds me of Sheba :-)<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=901315" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/1000-1999/1249/120/Copyrighted_Image_Reuse_Prohibited_901315.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/1000-1999/1249/120/Copyrighted_Image_Reuse_Prohibited_901315.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/1000-1999/1249/120/Copyrighted_Image_Reuse_Prohibited_901315.jpg"/></a></td>', 'Oh my, the incongruity is delightful.  But the look on her face reminds me of Sheba :-) ', '2010-11-28 12:48:20.000000', NULL, 1),
(6236113, 921168, 96751, '<td valign="top">Some nicely achieved elements here - I love the spill of light on the eye camera right, and the soft, reddish glow that highlights the dark side of the face.  The lit side is just a bit blown out in places, but somehow, it works.</td>', 'Some nicely achieved elements here - I love the spill of light on the eye camera right, and the soft, reddish glow that highlights the dark side of the face.  The lit side is just a bit blown out in places, but somehow, it works.', '2010-11-28 12:50:30.000000', NULL, 1),
