(6236155, 921073, 119179, '<td valign="top">Really great night portrait! Well done. <br/>It just misses a bit of "outdoor" imo. I would have go for the top mark with a bit more of that. Good job anyway. 8</td>', 'Really great night portrait! Well done. It just misses a bit of "outdoor" imo. I would have go for the top mark with a bit more of that. Good job anyway. 8', '2010-11-28 13:32:55.000000', NULL, 1),
(6236156, 921481, 119179, '<td valign="top">Really nice and interesting background, and effective use of the flash. Emotion brought by the subject could have been slightly better... But anyway, that is chic! 8</td>', 'Really nice and interesting background, and effective use of the flash. Emotion brought by the subject could have been slightly better... But anyway, that is chic! 8', '2010-11-28 13:33:05.000000', NULL, 1),
